-- =============================================================================
-- 6. DASHBOARDS, snapshots, scheduled reports  (FR-230..238, WG-xx)
-- =============================================================================
CREATE TABLE dashboards (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  container_id uuid /* id -> hierarchy.containers */,              -- NULL = workspace level; else space
  name text NOT NULL,
  owner_id uuid NOT NULL /* id -> identity.users */,
  visibility text NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','shared','workspace')),
  layout jsonb NOT NULL DEFAULT '[]',                       -- grid positions only
  template_id uuid /* id -> tasks.templates */,
  public_token_hash text, public_expires_at timestamptz,    -- FR-234 expiring read-only link
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE TABLE dashboard_widgets (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  dashboard_id uuid NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,
  widget_type text NOT NULL,                                -- catalogue key, e.g. status_count, burndown, time_tracked
  scope_container_id uuid /* id -> hierarchy.containers */,        -- data source scope
  filter jsonb NOT NULL DEFAULT '{}',
  group_by text,
  metric text,
  date_range jsonb,
  config jsonb NOT NULL DEFAULT '{}',                       -- chart options only, never filtered on
  position integer NOT NULL DEFAULT 0,
  last_refreshed_at timestamptz,                            -- FR-233
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX dashboard_widgets_dash ON dashboard_widgets (workspace_id, dashboard_id, position);

CREATE TABLE dashboard_shares (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  dashboard_id uuid NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,
  user_id uuid /* id -> identity.users */, group_id uuid /* id -> access.user_groups */,
  permission text NOT NULL DEFAULT 'view' CHECK (permission IN ('view','edit')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((user_id IS NULL) <> (group_id IS NULL))
);

-- Daily snapshots independent of current task state (FR-236, DR-016): burndown, burnup, cumulative flow.
CREATE TABLE daily_container_snapshots (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  container_id uuid NOT NULL /* id -> hierarchy.containers */,
  snapshot_date date NOT NULL,                              -- in the workspace time zone
  status_id uuid NOT NULL /* id -> hierarchy.task_statuses */,
  task_count integer NOT NULL,
  points numeric(12,2) NOT NULL DEFAULT 0,
  estimate_seconds bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (workspace_id, container_id, snapshot_date, status_id)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('daily_container_snapshots', 8);

CREATE TABLE scheduled_reports (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  dashboard_id uuid NOT NULL REFERENCES dashboards(id) ON DELETE CASCADE,
  cadence text NOT NULL CHECK (cadence IN ('daily','weekly','monthly')),
  send_at_local time NOT NULL, weekday smallint, month_day smallint,
  recipients jsonb NOT NULL DEFAULT '[]',
  format text NOT NULL DEFAULT 'pdf' CHECK (format IN ('pdf','png','csv')),
  active boolean NOT NULL DEFAULT true,
  next_run_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE project_health (                               -- FR-1103, WG-12 materialised, rule-based
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  container_id uuid NOT NULL /* id -> hierarchy.containers */,
  computed_at timestamptz NOT NULL,
  health text NOT NULL CHECK (health IN ('green','amber','red')),
  overdue_rate numeric(5,4), blocked_count integer, schedule_variance_days integer,
  PRIMARY KEY (workspace_id, container_id)
);

ALTER TABLE dashboards ADD COLUMN generated_by_ai boolean NOT NULL DEFAULT false;

ALTER TABLE dashboards ADD COLUMN source_prompt text;

-- shown so the user can see and edit what produced it
ALTER TABLE dashboards ADD COLUMN ai_request_id uuid;
